mapper.sql:
 FROM TB_LMS_SMSTR_CHRT S
 JOIN TB_LMS_ORG O
   ON S.ORG_ID = O.ORG_ID
 LEFT JOIN TB_LMS_ATNDC_SCR_CRTR_STNG C
   ON C.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID
WHERE NVL(O.USEYN, 'Y') = 'Y'

  AND S.ORG_ID = #{orgId}


  AND S.DGRS_YR = #{haksaYear}


  AND S.DGRS_SMSTR_CHRT = #{haksaTerm}

mapper.select:
/*
     SQL ID : AtndCrtrDAO.count
     메뉴명 : 출석점수 기준관리 목록 건수 조회
*/
SELECT COUNT(1)
  FROM TB_LMS_SMSTR_CHRT S
  JOIN TB_LMS_ORG O
    ON S.ORG_ID = O.ORG_ID
 WHERE NVL(O.USEYN, 'Y') = 'Y'

   AND S.ORG_ID = #{orgId}


   AND S.DGRS_YR = #{haksaYear}


   AND S.DGRS_SMSTR_CHRT = #{haksaTerm}

/* SQL ID : AtndCrtrDAO.listOrg 메뉴명 : 출석점수 기준관리 기관 목록 조회 */ SELECT O.ORG_ID , O.ORGNM , O.ORGNM AS ORG_NM , O.ORG_SHRTNM , O.ORG_SHRTNM AS ORG_SHRT_NM , O.ORG_TYCD FROM TB_LMS_ORG O WHERE NVL(O.USEYN, 'Y') = 'Y'
AND O.ORG_ID = #{orgId}
ORDER BY O.ORGNM ASC

/* SQL ID : AtndCrtrDAO.listHaksaTerm 메뉴명 : 출석점수 기준관리 학기(기수) 목록 조회 */ SELECT HAKSA_TERM , HAKSA_TERM_NM FROM ( SELECT S.DGRS_SMSTR_CHRT AS HAKSA_TERM , MAX(NVL(S.SMSTR_CHRTNM, S.DGRS_SMSTR_CHRT)) AS HAKSA_TERM_NM , CASE WHEN REGEXP_LIKE(S.DGRS_SMSTR_CHRT, '^[0-9]+$') THEN 0 ELSE 1 END AS TERM_NUMERIC_ORDER , AS TERM_NUMBER FROM TB_LMS_SMSTR_CHRT S JOIN TB_LMS_ORG O ON S.ORG_ID = O.ORG_ID WHERE NVL(O.USEYN, 'Y') = 'Y'
AND S.ORG_ID = #{orgId}
AND S.DGRS_YR = #{haksaYear}
GROUP BY S.DGRS_SMSTR_CHRT ) ORDER BY TERM_NUMERIC_ORDER, TERM_NUMBER, HAKSA_TERM

/*
     SQL ID : AtndCrtrDAO.select
     메뉴명 : 출석점수 기준관리 상세 조회
*/
SELECT 

   AND S.SMSTR_CHRT_ID = #{smstrChrtId}

/*
     SQL ID : AtndCrtrDAO.selectByOrgTerm
     메뉴명 : 기관/년도/학기 기준 학기기수 조회
*/
SELECT 

   AND S.ORG_ID = #{orgId}
   AND S.DGRS_YR = #{haksaYear}
   AND S.DGRS_SMSTR_CHRT = #{haksaTerm}

mapper.delete:
/*
     SQL ID : AtndCrtrDAO.deleteDtl
     메뉴명 : 출석점수 기준비율 삭제
*/
DELETE FROM TB_LMS_ATNDC_SCR_CRTR_STNG
 WHERE SMSTR_CHRT_ID = #{smstrChrtId}

   AND EXISTS (
         SELECT 1
           FROM TB_LMS_SMSTR_CHRT S
          WHERE S.SMSTR_CHRT_ID = #{smstrChrtId}
            AND S.ORG_ID = #{orgId}
       )

mapper.insert:
/*
     SQL ID : AtndCrtrDAO.insertDtl
     메뉴명 : 출석점수 기준비율 등록
*/
INSERT INTO TB_LMS_ATNDC_SCR_CRTR_STNG (
      CRTR_STNG_ID
    , SMSTR_CHRT_ID
    , STNG_SEQNO
    , STRT_AVG_PRGRT
    , END_AVG_PRGRT
    , ATNDC_SCR
    , RGTR_ID
    , REG_DTTM
    , MDFR_ID
    , MOD_DTTM
) VALUES (
      #{crtrStngId}
    , #{smstrChrtId}
    , #{crtrSeq}
    , #{startRate}
    , #{endRate}
    , #{score}
    , #{rgtrId}
    , FN_DTTM()
    , #{mdfrId}
    , FN_DTTM()
)

/*
     SQL ID : AtndCrtrDAO.insertWeekCrtr
     메뉴명 : 출결기준 및 진도율 설정 등록
*/
INSERT INTO TB_LMS_BYWKNO_ATTNDNC_CRTR (
      BYWKNO_ATTNDNC_CRTR_ID
    , SBJCT_ID
    , LRN_PRD_IN_PRGRT
    , LATE_RCG_PRD_IN_PRGRT
    , LATE_PRD_IN_PRGR_RCGRT
    , ABSNT_LATE_PRD_IN_PRGR_RCGRT
    , RGTR_ID
    , REG_DTTM
    , MDFR_ID
    , MOD_DTTM
) VALUES (
      #{bywknoAttndncCrtrId}
    , #{sbjctId}
    , #{atndMinPrgrt}
    , #{lateMinPrgrt}
    , #{lateRecgRate}
    , #{absentRecgRate}
    , #{rgtrId}
    , FN_DTTM()
    , #{mdfrId}
    , FN_DTTM()
)
